'use strict';
const examples=[{asset:'BTC / USDT',entry:75000,stop:73500,target:79500},{asset:'ETH / USDT',entry:2500,stop:2425,target:2725}];
const fmt=(n,d=2)=>new Intl.NumberFormat('es-ES',{maximumFractionDigits:d,minimumFractionDigits:d}).format(n);
let selected=0;
function selectPlan(index){selected=index;const p=examples[index];document.querySelectorAll('#plans tr').forEach((row,i)=>{row.classList.toggle('selected',i===index);row.querySelector('button').setAttribute('aria-pressed',String(i===index));});document.getElementById('detail').innerHTML=`<p class="eyebrow">EJEMPLO SELECCIONADO · ${p.asset}</p><h2>Un plan antes de entrar</h2><p>Niveles ficticios para explorar el portal. Sin análisis técnico ni vigencia de mercado.</p><div class="levels"><div>Stop-loss<strong>${fmt(p.stop)}</strong></div><div>Entrada limitada<strong>${fmt(p.entry)}</strong></div><div>Venta objetivo<strong>${fmt(p.target)}</strong></div></div>`;}
document.getElementById('plans').innerHTML=examples.map((p,i)=>`<tr><td><button type="button" data-index="${i}" aria-pressed="false">${p.asset}</button><small>Spot · ejemplo ficticio</small></td><td>${fmt(p.entry)}</td><td>${fmt(p.target)}</td><td>${fmt(p.stop)}</td><td><span class="status">Sin validar</span></td></tr>`).join('');
document.getElementById('plans').addEventListener('click',e=>{const b=e.target.closest('button');if(b)selectPlan(Number(b.dataset.index));});
function calculate(v){const {capital,risk,entry,stop,target,fee}=v;if(!Object.values(v).every(Number.isFinite)||capital<=0||risk<=0||risk>100||entry<=0||stop<=0||stop>=entry||target<=entry||fee<0||fee>10)throw new Error('Usa valores positivos, un stop inferior a la entrada y un objetivo superior. Riesgo: hasta 100 %. Comisión: de 0 a 10 %.');const f=fee/100;const loss=entry-stop+f*(entry+stop);const profit=target-entry-f*(entry+target);const quantity=Math.min(capital*risk/100/loss,capital/(entry*(1+f)));return{quantity,investment:quantity*entry,cost:quantity*entry*(1+f),loss:quantity*loss,profit:quantity*profit,ratio:profit/loss};}
function renderCalculation(){try{const values=Object.fromEntries(['capital','risk','entry','stop','target','fee'].map(k=>[k,document.getElementById(k).valueAsNumber]));const r=calculate(values);document.getElementById('results').innerHTML=`<div class="result"><p>Importe de compra <b>${fmt(r.investment)} USDT</b></p><p>Cantidad de activo <b>${fmt(r.quantity,8)}</b></p><p>Total con comisión de entrada <b>${fmt(r.cost)} USDT</b></p><p>Pérdida estimada en el stop <b>${fmt(r.loss)} USDT</b></p><p>Resultado neto en el objetivo <b>${fmt(r.profit)} USDT</b></p><p>Beneficio / riesgo neto <b>${fmt(r.ratio)} : 1</b></p></div>`;return r;}catch(e){document.getElementById('results').textContent=e.message;document.getElementById('results').className='error';return{error:e.message};}}
document.getElementById('calculator').addEventListener('submit',e=>{e.preventDefault();document.getElementById('results').className='';renderCalculation();});
selectPlan(0);renderCalculation();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_position_simulation',description:'Read the current fictional spot position simulation and its input values.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>{const inputs=Object.fromEntries(['capital','risk','entry','stop','target','fee'].map(k=>[k,document.getElementById(k).valueAsNumber]));return{inputs,result:calculate(inputs)};}})).catch(()=>{});}catch{}}

function showView(view){for(const name of ["portfolio","trading"]){document.getElementById(name+"-view").hidden=name!==view;document.getElementById(name+"-tab").setAttribute("aria-pressed",String(name===view));}}document.getElementById("portfolio-tab").addEventListener("click",()=>showView("portfolio"));document.getElementById("trading-tab").addEventListener("click",()=>showView("trading"));
